    quota: Vec<u64>,
    budget: Vec<u64>,

    /// Members of each group covering each cache node.
    cnt: Vec<u32>,
    /// Union of member footprints, as a bit set.
    union_fp: Vec<u64>,
    fp_size: Vec<i64>,
    members: Vec<i64>,
    load: Vec<i64>,
    /// Distinct (domain, class) pairs present in each group.
    keys: Vec<HashMap<(i64, i64), u32>>,
    g_dom: Vec<i64>,
    g_cls: Vec<i64>,

    usage: Vec<i64>,
    caps: Vec<i64>,
    over_flag: Vec<bool>,
    work_flag: Vec<bool>,

    overcap: i64,
    mixed: i64,
    workbad: i64,
    active: i64,
    slots: i64,
    total_weight: i64,
    pins: i64,
    pin_in_group: Vec<i64>,

    revision: u64,
    journal: Vec<Undo>,
    snaps: Vec<TaskSnap>,
    group_snaps: Vec<GroupSnap>,
    task_stamp: Vec<u32>,
    task_slot: Vec<u32>,
    group_stamp: Vec<u32>,
    group_slot: Vec<u32>,
    txn: u32,
}

impl Ledger {
    pub fn new(
        problem: &SolverProblem,
        domains: Vec<i64>,
        tasks: Vec<Task>,
        quotas: Vec<u64>,
        budgets: Vec<u64>,
        capacities: Vec<u64>,
    ) -> Result<Self, String> {
        let num_nodes = problem.num_nodes;
        if capacities.len() != num_nodes {
            return Err("capacity count".into());
        }
        if quotas.len() != budgets.len() {
            return Err("group table".into());
        }
        if domains.len() != problem.demands.len() {
            return Err("domain table".into());
        }
        for &cap in &capacities {
            if cap > i64::MAX as u64 {
                return Err("capacity range".into());
            }
        }
        let words = num_nodes.div_ceil(64);
        let templates = problem.demands.len();
        let mut template_fp = vec![0u64; templates * words];
        for (id, demand) in problem.demands.iter().enumerate() {
            for &node in &demand.footprint {
                if node >= num_nodes {
                    return Err("footprint node".into());
                }
                template_fp[id * words + node / 64] |= 1u64 << (node % 64);
            }
        }
        let groups = quotas.len();
        let task_count = tasks.len();
        for task in &tasks {
            if task.group >= groups {
                return Err("task group".into());
            }
            if task.template >= templates {
                return Err("task template".into());
            }
        }

        let mut ledger = Ledger {
            num_nodes,
            words,
            template_fp,
            dom: domains,
            task: tasks,
            quota: quotas,
            budget: budgets,
            cnt: vec![0u32; groups * num_nodes],
            union_fp: vec![0u64; groups * words],
            fp_size: vec![0i64; groups],
            members: vec![0i64; groups],
            load: vec![0i64; groups],
            keys: (0..groups).map(|_| HashMap::new()).collect(),
            g_dom: vec![-1i64; groups],
            g_cls: vec![-1i64; groups],
            usage: vec![0i64; num_nodes],
            caps: capacities.iter().map(|&x| x as i64).collect(),
            over_flag: vec![false; num_nodes],
            work_flag: vec![false; groups],
            overcap: 0,
            mixed: 0,
            workbad: 0,
            active: 0,
            slots: 0,
            total_weight: 0,
            pins: 0,
            pin_in_group: vec![0i64; groups],
            revision: 0,
            journal: Vec::new(),
            snaps: Vec::new(),
            group_snaps: Vec::new(),
            task_stamp: vec![0u32; task_count],
            task_slot: vec![0u32; task_count],
            group_stamp: vec![0u32; groups],
            group_slot: vec![0u32; groups],
            txn: 0,
        };
        for id in 0..ledger.task.len() {
            let group = ledger.task[id].group;
            ledger.attach(id, group);
        }
        if ledger.overcap != 0 || ledger.mixed != 0 || ledger.workbad != 0 {
            return Err("illegal initial configuration".into());
        }
        Ok(ledger)
    }

    // ---------------------------------------------------------------- state

    fn recheck_over(&mut self, node: usize) {
        let over = self.usage[node] > self.caps[node];
        if over != self.over_flag[node] {
            self.over_flag[node] = over;
            self.overcap += if over { 1 } else { -1 };
        }
    }

    fn update_work(&mut self, group: usize) {
        let bad = self.members[group] > 0
            && (self.quota[group] == 0
                || self.load[group] as i128 > self.quota[group] as i128 * self.budget[group] as i128);
        if bad != self.work_flag[group] {
            self.work_flag[group] = bad;
            self.workbad += if bad { 1 } else { -1 };
        }
    }

    fn bump_key(&mut self, group: usize, key: (i64, i64)) {
        let map = &mut self.keys[group];
        let prev = map.len();
        *map.entry(key).or_insert(0u32) += 1;
        let cur = map.len();
        if prev <= 1 && cur > 1 {
            self.mixed += 1;
        }
        if cur == 1 {
            self.g_dom[group] = key.0;
            self.g_cls[group] = key.1;
        }
    }

    fn drop_key(&mut self, group: usize, key: (i64, i64)) {
        let map = &mut self.keys[group];
        let prev = map.len();
        if let Some(count) = map.get_mut(&key) {
            *count -= 1;
            if *count == 0 {
                map.remove(&key);
            }
        }
        let cur = map.len();
        if prev > 1 && cur <= 1 {
            self.mixed -= 1;
        }
